inventory.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login, matches: []};
const mt = acct.membership_type, mid = acct.membership_id;
if (mt === null || mid === null) return {linked: true, error: "这个 Bungie 账号下没有命运2角色", matches: []};
const withPerks = args.with_perks !== false, withStats = args.with_stats === true;
const path = `/Destiny2/${mt}/Profile/${mid}/`;
const base = [102, 201, 205, 300];
let profile = await tools.destiny_read({path, query: {components: base.concat(withPerks ? [305] : [], withStats ? [304] : [])}, max_chars: 3500000});
if (profile.too_large) profile = await tools.destiny_read({path, query: {components: base}, max_chars: 3500000});
if (profile.too_large) throw new Error("库存响应超过上限");
const cls = {};
for (const c of acct.characters) cls[c.character_id] = c.class;
const owned = [];
for (const it of profile.profileInventory?.data?.items ?? []) owned.push({it, location: "仓库", character_id: null, equipped: false});
for (const [cid, inv] of Object.entries(profile.characterInventories?.data ?? {}))
  for (const it of inv.items ?? []) owned.push({it, location: `${cls[cid] ?? cid}背包`, character_id: cid, equipped: false});
for (const [cid, inv] of Object.entries(profile.characterEquipment?.data ?? {}))
  for (const it of inv.items ?? []) owned.push({it, location: `${cls[cid] ?? cid}已装备`, character_id: cid, equipped: true});
const define = async (kind, hashes, into) => {
  const todo = [...new Set(hashes.filter(h => h && !(h in into)))];
  for (let i = 0; i < todo.length; i += 500) Object.assign(into, (await tools.destiny_lookup({kind, hashes: todo.slice(i, i + 500)})).definitions);
};
const defs = {};
await define("item", owned.map(x => x.it.itemHash), defs);
const q = (args.query ?? "").trim().toLowerCase();
let alias = new Set();
if (q) {
  const found = await max.raw("destiny_lookup", {kind: "item", search: args.query, limit: 50});
  if (found.outcome === "succeeded") alias = new Set(found.value.results.map(r => r.hash));
}
const slot = args.slot ?? "all";
const slotOk = d => slot === "all" || (slot === "weapon" && d.itemType === 3) || (slot === "armor" && d.itemType === 2) || (slot === "gear" && (d.itemType === 2 || d.itemType === 3));
const hits = owned.filter(({it}) => {
  const d = defs[it.itemHash];
  return d && slotOk(d) && (!q || (d.name ?? "").toLowerCase().includes(q) || alias.has(it.itemHash));
});
const instances = profile.itemComponents?.instances?.data ?? {};
const sockets = profile.itemComponents?.sockets?.data ?? {};
const stats = profile.itemComponents?.stats?.data ?? {};
// Weapon perks, intrinsic traits, armor perks (exotic intrinsics).
const perkCategories = new Set([4241085061, 3956125808, 3154740035]);
const perkHashes = row => {
  const live = sockets[row.it.itemInstanceId]?.sockets ?? [];
  return (defs[row.it.itemHash].sockets ?? []).filter(s => perkCategories.has(s.category)).map(s => live[s.index]).filter(p => p && p.plugHash && p.isVisible !== false).map(p => p.plugHash);
};
const limit = Math.min(args.limit ?? 30, 60);
hits.sort((a, b) => (defs[a.it.itemHash].name ?? "").localeCompare(defs[b.it.itemHash].name ?? "") || (instances[b.it.itemInstanceId]?.primaryStat?.value ?? 0) - (instances[a.it.itemInstanceId]?.primaryStat?.value ?? 0));
const shown = hits.slice(0, limit);
const plugs = {}, statDefs = {};
if (withPerks) await define("item", shown.flatMap(perkHashes), plugs);
if (withStats) await define("stat", shown.flatMap(r => Object.keys(stats[r.it.itemInstanceId]?.stats ?? {}).map(Number)), statDefs);
const damage = {1: "动能", 2: "电弧", 3: "烈日", 4: "虚空", 6: "冰影", 7: "缚丝"};
const rows = shown.map(row => {
  const d = defs[row.it.itemHash], inst = instances[row.it.itemInstanceId] ?? {}, state = row.it.state ?? 0;
  const out = {name: d.name, type: d.type, tier: d.tier, hash: row.it.itemHash, item_id: row.it.itemInstanceId ?? null, location: row.location, character_id: row.character_id, equipped: row.equipped};
  if ((row.it.quantity ?? 1) > 1) out.quantity = row.it.quantity;
  if (inst.primaryStat?.value) out.power = inst.primaryStat.value;
  if (damage[inst.damageType]) out.damage = damage[inst.damageType];
  if (state & 1) out.locked = true;
  if (state & 4) out.masterwork = true;
  if (state & 8) out.crafted = true;
  if (withPerks) {
    const names = perkHashes(row).map(h => plugs[h]?.name).filter(Boolean);
    if (names.length) out.perks = names;
  }
  if (withStats && stats[row.it.itemInstanceId]) {
    out.stats = Object.fromEntries(Object.values(stats[row.it.itemInstanceId].stats).filter(s => s.value).map(s => [statDefs[s.statHash]?.name ?? String(s.statHash), s.value]));
  }
  return out;
});
return {bungie_name: acct.bungie_name, total_items: owned.length, matched: hits.length, shown: rows.length, vault_visible: Boolean(profile.profileInventory?.data), matches: rows};

move.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {ok: false, error: acct.login, steps: []};
const mt = acct.membership_type, mid = acct.membership_id;
const profile = await tools.destiny_read({path: `/Destiny2/${mt}/Profile/${mid}/`, query: {components: [102, 201, 205]}, max_chars: 3500000});
if (profile.too_large) throw new Error("库存响应超过上限");
let found = null;
for (const it of profile.profileInventory?.data?.items ?? []) if (it.itemInstanceId === args.item_id) found = {it, owner: null, equipped: false};
for (const [cid, inv] of Object.entries(profile.characterInventories?.data ?? {}))
  for (const it of inv.items ?? []) if (it.itemInstanceId === args.item_id) found = {it, owner: cid, equipped: false};
for (const [cid, inv] of Object.entries(profile.characterEquipment?.data ?? {}))
  for (const it of inv.items ?? []) if (it.itemInstanceId === args.item_id) found = {it, owner: cid, equipped: true};
if (!found) return {ok: false, error: "仓库和各角色身上都没有这个 item_id（可能已被移动或分解，重新查一次）", steps: []};
const target = args.to === "vault" ? null : args.to;
const cls = {};
for (const c of acct.characters) cls[c.character_id] = c.class;
if (target !== null && !(target in cls)) return {ok: false, error: "to 必须是 \"vault\" 或你自己的 character_id", steps: []};
if (args.equip && target === null) return {ok: false, error: "仓库里不能装备；equip 需要目标角色", steps: []};
const steps = [];
const act = async (label, action, body) => {
  const r = await max.raw("destiny_write", {path: `/Destiny2/Actions/Items/${action}/`, body: {...body, membershipType: mt}});
  const ok = r.outcome === "committed" || r.outcome === "succeeded";
  steps.push(ok ? {step: label, ok} : {step: label, ok, outcome: r.outcome, error: r.error?.message});
  return ok;
};
const it = found.it;
const transfer = (toVault, cid) => act(toVault ? `从${cls[cid]}放进仓库` : `从仓库取到${cls[cid]}`, "TransferItem", {itemReferenceHash: it.itemHash, stackSize: it.quantity ?? 1, transferToVault: toVault, itemId: it.itemInstanceId, characterId: cid});
const equip = cid => act(`给${cls[cid]}装备`, "EquipItem", {itemId: it.itemInstanceId, characterId: cid});
const result = ok => ({ok, item_id: it.itemInstanceId, from: found.owner === null ? "仓库" : cls[found.owner] + (found.equipped ? "（已装备）" : ""), to: target === null ? "仓库" : cls[target], steps});
if (found.owner === target) {
  if (!args.equip || found.equipped) return {...result(true), note: found.equipped ? "已经装备在这个角色上" : "已经在这个角色背包里"};
  return result(await equip(target));
}
if (found.equipped) {
  // An equipped item cannot move; equip another from the same slot first, preferring non-exotics.
  const candidates = (profile.characterInventories?.data?.[found.owner]?.items ?? []).filter(x => x.bucketHash === it.bucketHash && x.itemInstanceId);
  if (!candidates.length) return {...result(false), error: "这件正装备着，而这个角色背包里同栏位没有能换上的物品"};
  const defs = (await tools.destiny_lookup({kind: "item", hashes: [...new Set(candidates.map(x => x.itemHash))]})).definitions;
  candidates.sort((a, b) => ((defs[a.itemHash]?.tierType === 6) - (defs[b.itemHash]?.tierType === 6)));
  const swap = candidates[0];
  const swapped = await act(`先给${cls[found.owner]}换上「${defs[swap.itemHash]?.name ?? swap.itemHash}」`, "EquipItem", {itemId: swap.itemInstanceId, characterId: found.owner});
  if (!swapped) return result(false);
}
if (found.owner !== null && !(await transfer(true, found.owner))) return result(false);
if (target !== null && !(await transfer(false, target))) return result(false);
if (target !== null && args.equip && !(await equip(target))) return result(false);
return result(true);

recent.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login, activities: []};
const mt = acct.membership_type, mid = acct.membership_id;
const chars = args.character_id ? acct.characters.filter(c => c.character_id === args.character_id) : acct.characters;
if (!chars.length) return {linked: true, error: "没有匹配的角色", activities: []};
const count = Math.min(args.count ?? 10, 25);
const pages = await Promise.all(chars.map(c => max.raw("destiny_read", {path: `/Destiny2/${mt}/Account/${mid}/Character/${c.character_id}/Stats/Activities/`, query: {count, mode: args.mode ?? 0, page: 0}})));
const rows = [], errors = [];
pages.forEach((page, i) => {
  if (page.outcome !== "succeeded") errors.push({class: chars[i].class, error: page.error?.message});
  else for (const a of page.value.activities ?? []) rows.push({c: chars[i], a});
});
rows.sort((x, y) => y.a.period.localeCompare(x.a.period));
const shown = rows.slice(0, count);
const hashes = [...new Set(shown.flatMap(r => [r.a.activityDetails.referenceId, r.a.activityDetails.directorActivityHash]).filter(Boolean))];
const names = hashes.length ? (await tools.destiny_lookup({kind: "activity", hashes})).definitions : {};
const modes = {2: "剧情", 3: "打击", 4: "突袭", 5: "PvP", 6: "巡逻", 7: "PvE", 10: "占领", 12: "冲突", 18: "打击", 19: "铁旗", 25: "混战", 46: "宗师/日落", 48: "混战", 63: "智谋", 69: "竞技", 70: "快速比赛", 82: "地牢", 84: "试炼", 87: "失落区域"};
const value = (a, key) => a.values?.[key]?.basic?.value;
const display = (a, key) => a.values?.[key]?.basic?.displayValue;
return {
  bungie_name: acct.bungie_name,
  activities: shown.map(({c, a}) => {
    const d = a.activityDetails;
    const out = {
      time: a.period, class: c.class,
      activity: names[d.directorActivityHash]?.name ?? names[d.referenceId]?.name ?? String(d.referenceId),
      mode: modes[d.mode] ?? `mode ${d.mode}`,
      completed: value(a, "completed") === 1,
      kills: value(a, "kills"), deaths: value(a, "deaths"), assists: value(a, "assists"),
      kd: display(a, "killsDeathsRatio"), duration: display(a, "timePlayedSeconds"),
      instance_id: d.instanceId
    };
    const standing = display(a, "standing");
    if (standing) out.standing = standing;
    return out;
  }),
  errors
};

pgcr.source:
const report = await tools.destiny_read({path: `/Destiny2/Stats/PostGameCarnageReport/${args.instance_id}/`, max_chars: 3500000});
if (report.too_large) throw new Error("PGCR 响应超过上限");
const account = await max.raw("destiny_account", {});
const me = account.outcome === "succeeded" && account.value.linked ? account.value.membership_id : null;
const value = (values, key) => values?.[key]?.basic?.value;
const display = (values, key) => values?.[key]?.basic?.displayValue;
const entries = report.entries ?? [];
const details = report.activityDetails ?? {};
const weaponHashes = entries.flatMap(e => (e.extended?.weapons ?? []).map(w => w.referenceId));
const activityHashes = [details.directorActivityHash, details.referenceId].filter(Boolean);
const [weapons, activities] = await Promise.all([
  weaponHashes.length ? tools.destiny_lookup({kind: "item", hashes: [...new Set(weaponHashes)].slice(0, 500)}) : {definitions: {}},
  activityHashes.length ? tools.destiny_lookup({kind: "activity", hashes: [...new Set(activityHashes)]}) : {definitions: {}}
]);
const classes = {3655393761: "泰坦", 671679327: "猎人", 2271682572: "术士"};
const modes = {2: "剧情", 3: "打击", 4: "突袭", 5: "PvP", 6: "巡逻", 7: "PvE", 10: "占领", 12: "冲突", 18: "打击", 19: "铁旗", 25: "混战", 46: "宗师/日落", 48: "混战", 63: "智谋", 69: "竞技", 70: "快速比赛", 82: "地牢", 84: "试炼", 87: "失落区域"};
const name = info => info?.bungieGlobalDisplayName ? `${info.bungieGlobalDisplayName}#${String(info.bungieGlobalDisplayNameCode ?? 0).padStart(4, "0")}` : (info?.displayName ?? "?");
const players = entries.map(e => {
  const info = e.player?.destinyUserInfo ?? {};
  const ext = e.extended?.values ?? {};
  const out = {
    name: name(info),
    class: classes[e.player?.classHash] ?? e.player?.characterClass,
    light: e.player?.lightLevel,
    kills: value(e.values, "kills"), deaths: value(e.values, "deaths"), assists: value(e.values, "assists"),
    kd: display(e.values, "killsDeathsRatio"),
    completed: value(e.values, "completed") === 1,
    time_played: display(e.values, "timePlayedSeconds"),
    weapons: (e.extended?.weapons ?? [])
      .map(w => ({name: weapons.definitions[w.referenceId]?.name ?? String(w.referenceId), kills: value(w.values, "uniqueWeaponKills") ?? 0, precision: value(w.values, "uniqueWeaponPrecisionKills") ?? 0}))
      .sort((a, b) => b.kills - a.kills).slice(0, 3),
    abilities: {grenade: value(ext, "weaponKillsGrenade") ?? 0, melee: value(ext, "weaponKillsMelee") ?? 0, super: value(ext, "weaponKillsSuper") ?? 0}
  };
  if (me && info.membershipId === me) out.me = true;
  if (value(e.values, "team") !== undefined) out.team = value(e.values, "team");
  if (display(e.values, "standing")) out.standing = display(e.values, "standing");
  if (value(e, "score") !== undefined && value(e, "score") !== 0) out.score = value(e, "score");
  return out;
}).sort((a, b) => (b.kills ?? 0) - (a.kills ?? 0)).slice(0, args.max_players ?? 12);
const first = entries[0]?.values ?? {};
return {
  instance_id: args.instance_id,
  period: report.period,
  activity: activities.definitions[details.directorActivityHash]?.name ?? activities.definitions[details.referenceId]?.name ?? String(details.referenceId),
  mode: modes[details.mode] ?? `mode ${details.mode}`,
  duration: display(first, "activityDurationSeconds"),
  from_beginning: report.activityWasStartedFromBeginning,
  completed: players.some(p => p.completed),
  player_count: entries.length,
  teams: (report.teams ?? []).map(t => ({team: t.teamId, name: t.teamName, standing: display(t, "standing") ?? t.standing?.basic?.displayValue, score: t.score?.basic?.value})),
  players
};
